# Minimum on-screen separation between two markers, in % of the map width.
# Overlapping markers are gently fanned out and joined to their true position
# by a hair-line, so city clusters (Madrid, Barcelona, Londres…) stay readable.
MIN_MARKER_SEPARATION = 2.6

