# =============================================================================
#  CALIBRATION — projection of the two bundled map images (do not edit)
# =============================================================================
# Fitted against known coastal landmarks / island centroids.
# Residuals: España RMS 3.5 px, Europa RMS 2.6 px (on 2048 px maps ≈ 0.15 %).

_ES_CAL = {
    "cx": (1323.8047749745606, 131.44706674153693, 1.7813373982940994),
    "cy": (7961.308119575752, 0.31483829019825293, -173.44368334383762),
    "size": 2048.0,
}
_EU_CAL = {
    "lon0": 7.6991623,
    "lat0": 52.53022335,
    "cx": (703.9833027121945, 2503.281874663894, 115.24040170169397),
    "cy": (1186.6992124237095, 119.0413649040106, -2510.206363144077),
    "size": 2048.0,
}


def project_spain(lat: float, lon: float) -> tuple[float, float]:
    """(lat, lon) -> (left %, top %) on the Spain map. Equirectangular + affine."""
    cx, cy, s = _ES_CAL["cx"], _ES_CAL["cy"], _ES_CAL["size"]
    x = cx[0] + cx[1] * lon + cx[2] * lat
    y = cy[0] + cy[1] * lon + cy[2] * lat
    return x / s * 100.0, y / s * 100.0


def project_europe(lat: float, lon: float) -> tuple[float, float]:
    """(lat, lon) -> (left %, top %) on the Europe map. Lambert azimuthal EA + affine."""
    lam = math.radians(lon - _EU_CAL["lon0"])
    phi = math.radians(lat)
    phi0 = math.radians(_EU_CAL["lat0"])
    k = math.sqrt(2.0 / (1.0 + math.sin(phi0) * math.sin(phi)
                         + math.cos(phi0) * math.cos(phi) * math.cos(lam)))
    u = k * math.cos(phi) * math.sin(lam)
    v = k * (math.cos(phi0) * math.sin(phi) - math.sin(phi0) * math.cos(phi) * math.cos(lam))
    cx, cy, s = _EU_CAL["cx"], _EU_CAL["cy"], _EU_CAL["size"]
    x = cx[0] + cx[1] * u + cx[2] * v
    y = cy[0] + cy[1] * u + cy[2] * v
    return x / s * 100.0, y / s * 100.0


def _placed(rows: list[dict], projector) -> list[dict]:
    out = []
    for r in rows:
        left, top = projector(r["lat"], r["lon"])
        out.append({
            "name": r["name"],
            "place": r.get("place", ""),
            "status": r["status"],
            "url": r.get("url", ""),
            "left": round(left, 3),
            "top": round(top, 3),
        })
    return out


