def main() -> None:
    st.set_page_config(page_title=PAGE_TITLE, page_icon="🗺️", layout="wide")
    st.markdown(
        """
        <style>
          .block-container{ padding:0 1rem 1rem 1rem; max-width:100%; }
          [data-testid="stHeader"]{ background:transparent; }
        </style>
        """,
        unsafe_allow_html=True,
    )

    components.html(build_html(), height=COMPONENT_HEIGHT, scrolling=True)

    rows = []
    for scope, data in (("España (SICUE)", SPAIN),
                        ("Europa (Erasmus)", EUROPE),
                        ("Fuera de Europa", OUTSIDE_EUROPE)):
        for u in data:
            rows.append({
                "Ámbito": scope,
                "Universidad": u["name"],
                "Lugar": u.get("place", ""),
                "Estado": STATUSES[u["status"]][0],
                "Lat": u.get("lat"),
                "Lon": u.get("lon"),
                "Web": u.get("url", ""),
            })
    df = pd.DataFrame(rows)

    with st.expander(f"Listado completo ({len(df)} instituciones)", expanded=False):
        st.dataframe(
            df,
            hide_index=True,
            column_config={"Web": st.column_config.LinkColumn("Web", display_text="abrir")},
        )
        st.download_button(
            "Descargar CSV",
            df.to_csv(index=False).encode("utf-8"),
            file_name="movilidad_sicue_erasmus.csv",
            mime="text/csv",
        )


